import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with customer, date and lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
});

test('createInvoice copies name, unitPrice and vatRate from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const line = result.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for bad date format', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for non-existent date', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for invalid month', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for fractional quantity', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5.5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with different quantities', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 8500 }), 850000);
});

test('lineTotal works with different unit prices', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 100 }), 500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 1 }), 5);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 5 * 8500 + 10 * 9500);
  assert.equal(totals.subtotal, 137500);
});

test('invoiceTotals returns total equal to subtotal', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.total, 25500);
});

test('invoiceTotals handles multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
      { sku: 'SUPPORT-HOUR', qty: 1 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const expected = 2 * 8500 + 3 * 9500 + 1 * 7250;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine copies product details from catalogue', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 2 });
  const line = result.value.lines[1];
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('addLine validates qty like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice.value, { sku: 'DEV-HOUR', qty: 5.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(invoice.value, { sku: 'NOPE', qty: 3 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const nonDraft = { ...invoice.value, status: 'sent' };
  assert.deepEqual(addLine(nonDraft, { sku: 'DEV-HOUR', qty: 3 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const copy = JSON.parse(JSON.stringify(invoice));
  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.deepEqual(invoice, copy);
});

test('removeLine removes a line by SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const result = removeLine(invoice.value, 'DES-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(invoice.value, 'NOPE'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(invoice.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const nonDraft = { ...invoice.value, status: 'sent' };
  assert.deepEqual(removeLine(nonDraft, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the input', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const copy = JSON.parse(JSON.stringify(invoice));
  removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(invoice, copy);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = issueInvoice(invoice.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
});

test('issueInvoice includes all lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const result = issueInvoice(invoice.value, []);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
});

test('issueInvoice calculates next number based on existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const result = issueInvoice(invoice.value, existing);
  assert.equal(result.value.number, 'INV-2026-0003');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = { ...invoice.value, status: 'issued' };
  assert.deepEqual(issueInvoice(issued, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the input', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const copy = JSON.parse(JSON.stringify(invoice));
  issueInvoice(invoice, []);
  assert.deepEqual(invoice, copy);
});

