  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 15);
});

test('addLine reports DISCOUNT_INVALID for invalid discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const result = addLine(invoice.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 150 });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

